let rawLog = msg.payload;

msg.payload = rawLog.map(({ 
    text,
    timeCreated,
    loggedByFullName,
    client
}) => ({
    content: text || "",
    callsign: `[${client}] ${loggedByFullName}` || "Unknown",
    createdAt: new Date(timeCreated).toISOString(),
    location: false,
    replyMessageId: null,
    files: []
}));

return msg;
